{"script": "repo.edit("src/cache.rs", "pub const CAPACITY: usize = 16;", "pub const CAPACITY: usize = 32;")

res = env.run(["cargo", "test"], check = False)

tail = str(text(res.stdout).tail(120)) + "\n--- stderr ---\n" + str(text(res.stderr).tail(60))

if res.code != 0:
    discard({
        "status": "FAILED - change reverted",
        "exit_code": res.code,
        "test_output_tail": tail,
        "reverted_diff": repo.diff(),
    })

result({
    "status": "PASSED - change kept",
    "exit_code": res.code,
    "files_changed": [{"path": s.path, "kind": s.kind} for s in repo.status()],
    "diff": repo.diff(),
    "test_output_tail": tail,
})
"}

